package android.os;import java.io.*;public class ParcelFileDescriptor implements Closeable{public static final int MODE_WRITE_ONLY=0x20000000,MODE_CREATE=0x08000000,MODE_APPEND=0x02000000,MODE_TRUNCATE=0x04000000,MODE_READ_ONLY=0x10000000;RandomAccessFile file;private ParcelFileDescriptor(File f,int mode)throws IOException{file=new RandomAccessFile(f,(mode&MODE_WRITE_ONLY)!=0?"rw":"r");if((mode&MODE_TRUNCATE)!=0)file.setLength(0);if((mode&MODE_APPEND)!=0)file.seek(file.length());}public static ParcelFileDescriptor open(File f,int mode)throws FileNotFoundException{try{return new ParcelFileDescriptor(f,mode);}catch(IOException e){throw new FileNotFoundException(e.toString());}}public FileDescriptor getFileDescriptor(){try{return file.getFD();}catch(IOException e){throw new RuntimeException(e);}}public void close()throws IOException{file.close();}}
